  "ui.surface.close": { params: UiSurfaceCloseParams; result: UiSurfaceCloseResult };
  "ui.notify": { params: UiNotifyParams; result: UiNotifyResult };
  "perm.request": { params: PermRequestParams; result: PermRequestResult };
